BEGIN;
CREATE TABLE IF NOT EXISTS departments(id text PRIMARY KEY,name text NOT NULL,code text NOT NULL UNIQUE,enabled boolean NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,display_name text NOT NULL,avatar_url text NOT NULL DEFAULT '',department_id text REFERENCES departments(id),role text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS classifications(id text PRIMARY KEY,parent_id text REFERENCES classifications(id),name text NOT NULL,code text NOT NULL UNIQUE,sort_order integer NOT NULL DEFAULT 0,enabled boolean NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,CHECK(id<>parent_id));
CREATE TABLE IF NOT EXISTS case_files(id text PRIMARY KEY,case_number text NOT NULL UNIQUE,title text NOT NULL,classification_id text NOT NULL REFERENCES classifications(id),security_level text NOT NULL,retention text NOT NULL,responsible_department text NOT NULL REFERENCES departments(id),handler_id text NOT NULL REFERENCES users(id),year integer NOT NULL,keywords_json text NOT NULL DEFAULT '[]',summary text NOT NULL DEFAULT '',status text NOT NULL,version integer NOT NULL DEFAULT 1,created_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,destroyed_reason text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS materials(id text PRIMARY KEY,case_id text NOT NULL REFERENCES case_files(id) ON DELETE CASCADE,title text NOT NULL,page_from integer NOT NULL,page_to integer NOT NULL,document_at timestamptz NOT NULL,responsible text NOT NULL,attachment_id text,created_at timestamptz NOT NULL,CHECK(page_from>0 AND page_to>=page_from));
CREATE TABLE IF NOT EXISTS case_versions(id text PRIMARY KEY,case_id text NOT NULL REFERENCES case_files(id),version integer NOT NULL,reason text NOT NULL,changed_by text NOT NULL REFERENCES users(id),snapshot_json text NOT NULL,diff_json text NOT NULL,created_at timestamptz NOT NULL,UNIQUE(case_id,version));
CREATE TABLE IF NOT EXISTS reviews(id text PRIMARY KEY,case_id text NOT NULL REFERENCES case_files(id),reviewer_id text NOT NULL REFERENCES users(id),approved boolean NOT NULL,opinion text NOT NULL,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS borrow_requests(id text PRIMARY KEY,case_id text NOT NULL REFERENCES case_files(id),applicant_id text NOT NULL REFERENCES users(id),approver_id text REFERENCES users(id),purpose text NOT NULL,status text NOT NULL,due_at timestamptz NOT NULL,checked_out_at timestamptz,returned_at timestamptz,renewals integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_checkout ON borrow_requests(case_id) WHERE status IN('checked_out','overdue');
CREATE TABLE IF NOT EXISTS attachments(id text PRIMARY KEY,case_id text NOT NULL REFERENCES case_files(id),material_id text,original_name text NOT NULL,storage_key text NOT NULL UNIQUE,content_type text NOT NULL,size bigint NOT NULL,sha256 char(64) NOT NULL,version integer NOT NULL,uploaded_by text NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,actor_id text,action text NOT NULL,resource text NOT NULL,resource_id text NOT NULL,reason text NOT NULL DEFAULT '',request_id text NOT NULL,metadata_json text NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS idx_audit_timeline ON audit_events(resource,resource_id,created_at DESC);
CREATE TABLE IF NOT EXISTS refresh_tokens(hash char(64) PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),family_id text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,revoked_at timestamptz);
COMMIT;
